import{_ as i,o as a,c as n,j as e,a as o,aa as r}from"./chunks/framework.BAs_AphD.js";const s="/buildary-help-preview/media/en/diary/en_btn_novy_denik.jpg",d="/buildary-help-preview/media/en/diary/en_btn_novy_denik_kopii.png",c="/buildary-help-preview/media/en/diary/en_novydenik.jpg",l="/buildary-help-preview/media/en/diary/en_provazane_deniky.jpg",h="/buildary-help-preview/media/en/diary/en_nastaveni_deniku2.jpg",p="/buildary-help-preview/media/en/diary/en_nastavenipocasi.jpg",S=JSON.parse('{"title":"Creating and Setting Up a Diary","description":"","frontmatter":{"title":"Creating and Setting Up a Diary","wiki":"en:diary:diarysetup"},"headers":[],"relativePath":"en/diary/diarysetup.md","filePath":"en/diary/diarysetup.md","lastUpdated":1795418601000}'),u={name:"en/diary/diarysetup.md"};function y(g,t,m,f,b,w){return a(),n("div",null,[...t[0]||(t[0]=[e("h1",{id:"creating-and-setting-up-a-diary",tabindex:"-1"},[o("Creating and Setting Up a Diary "),e("a",{class:"header-anchor",href:"#creating-and-setting-up-a-diary","aria-label":'Permalink to "Creating and Setting Up a Diary"'},"​")],-1),e("div",{class:"video"},[e("iframe",{src:"https://www.youtube-nocookie.com/embed/zKdiW74IGV8",title:"YouTube video",loading:"lazy",allowfullscreen:"",allow:"accelerometer; encrypted-media; gyroscope; picture-in-picture"})],-1),r('<p>Each construction site can have any number of diaries. Especially on large construction sites, separate diaries are maintained for each building object. Shared information at the construction-site level is then recorded in what is known as the central Project Diary. In practice, it is also common for major subcontractors to maintain their own Project Diaries. Sometimes it is appropriate to maintain separate diaries for certain special types of work that require this due to their nature. The <strong>Buildary</strong> application can easily handle all of these scenarios.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>If you already have a proven system for structuring diaries on your construction sites, there is no reason to change it. Buildary supports it.</p></div><h2 id="creating-a-diary" tabindex="-1">Creating a Diary <a class="header-anchor" href="#creating-a-diary" aria-label="Permalink to &quot;Creating a Diary&quot;">​</a></h2><p>You can create a new diary from the <strong>Diary List</strong> using the <img src="'+s+'" alt="Create New Diary button" data-no-zoom loading="lazy"></p><p>Another option is to <strong>create a diary by copying</strong> one of the existing construction site diaries. In addition to the settings, you can also copy the Authorized Persons. To create a diary by copying, use the <img src="'+d+'" alt="Create Diary by Copying button" data-no-zoom loading="lazy"></p><figure class="shot" style="--w:600px;"><img src="'+c+'" alt="New Diary window" loading="lazy"></figure><p>In the <strong>New Diary</strong> window, enter:</p><p><strong>Diary Type</strong> - select the diary type that suits your needs from the list. The diary type affects the order in which diaries are displayed in the construction site diary list.</p><p><strong>Diary owner</strong> - select the company responsible for maintaining the diary from the code list.</p><p><strong>Document Type</strong> - information about the type of document on the basis of which the construction site is being carried out.</p><p><strong>Diary Start Date</strong> - the start date of the Project Diary, usually the date when the construction site was handed over. The date can be set as needed, either in the past or in the future.</p><p><strong>Diary Finish Date</strong> - after this date, daily entries can no longer be added. This field does not have to be filled in.</p><h3 id="specific-information-for-certain-diary-types" tabindex="-1">Specific Information for Certain Diary Types <a class="header-anchor" href="#specific-information-for-certain-diary-types" aria-label="Permalink to &quot;Specific Information for Certain Diary Types&quot;">​</a></h3><figure class="shot" style="--w:650px;"><img src="'+l+'" alt="Linked Diaries" width="600" loading="lazy"></figure><p>For diaries of the following types:</p><ul><li>Project Diary /part of construction site/ (i.e. building-object diary)</li><li>Subcontractor Diary</li><li>Special Works Diary</li></ul><p>additional information must be entered, such as <strong>Construction Site Section Name</strong>, <strong>Short Construction Site Section Name</strong>, and <strong>Construction Site Section Number</strong>. The meaning of these fields is clear from their names.</p><p>The <strong>Parent Diary</strong> field allows you to create a hierarchical relationship between two diaries. This relationship then allows data to be copied from relevant subordinate diaries (see <a href="/buildary-help-preview/en/diary/copysubcontractors">Copying Entries from Subcontractor Diaries and Construction Site Section Diaries</a>).</p><h2 id="diary-settings" tabindex="-1">Diary Settings <a class="header-anchor" href="#diary-settings" aria-label="Permalink to &quot;Diary Settings&quot;">​</a></h2><p>Before entering data into the diary, it is advisable to configure it so that its contents best meet your needs. Diary settings primarily affect the content of daily entries.</p><p><strong>Diary Settings</strong> can be accessed in several ways:</p><ul><li>from the <strong>Diary List</strong> by clicking the pencil icon at the end of the row for the relevant diary, and then selecting the Diary Settings tab;</li><li>if you are viewing the Daily Entries of a diary, simply click the <strong>Diary Settings</strong> button with the gear icon above the timeline, or</li><li>select <strong>Identification Details</strong> in the left panel and then select the <strong>Diary Settings</strong> tab</li></ul><p>The <strong>Diary Settings</strong> window contains tabs for configuring individual sections. The individual tabs are described below.</p><h3 id="basic" tabindex="-1">Basic <a class="header-anchor" href="#basic" aria-label="Permalink to &quot;Basic&quot;">​</a></h3><figure class="shot" style="--w:600px;"><img src="'+h+'" alt="" width="600" loading="lazy"></figure><p><strong>Time Limit for Signature</strong> - specifies the time in minutes for which a Daily Entry or Other Entry will be temporarily locked after the <strong>Download for Signing</strong> function is initiated. The temporary lock ends either with a permanent lock (i.e. by signing the entry or uploading the electronically signed entry back into the application) or when the configured time expires and the entry returns to its active state. A file uploaded after the time limit has expired will be rejected.</p><p><strong>Number of Signature fields</strong> - specifies the number of signature fields at the end of the entry being signed. According to common practice, the daily report is signed by the Site Manager and the Technical Supervision Representative (TDS), so two signature fields are configured by default. The number can be changed as needed.</p><p><strong>Working Hours</strong> - the contents of this field are automatically inserted into the note in the Labour section when the first entry is added to this section. The note can be edited for individual days.</p><p><strong>Working Day Hours</strong> - determines the number of working hours that will be offered by default for Labour and Plants in the Hours field.</p><p><strong>Other Entries Signature Check</strong> - this field is checked by default and means that a day cannot be locked without signatures for all entries made by other people in the Other Entries section.</p><p><strong>Attendance Import</strong> - this section is displayed only if at least one attendance system is connected to the project&#39;s domain. Select the attendance system and the terminal at the construction site; with the contractor ID filter, subcontractor diaries can import only people belonging to the given subcontractor. See <a href="/buildary-help-preview/en/diary/attendance_system#select-the-attendance-system-in-a-diary">Project Attendance System</a>.</p><p><strong>Section Order</strong> - allows you to change the order of sections according to your requirements.</p><h3 id="individual-section-tabs-common-information" tabindex="-1">Individual Section Tabs - Common Information <a class="header-anchor" href="#individual-section-tabs-common-information" aria-label="Permalink to &quot;Individual Section Tabs - Common Information&quot;">​</a></h3><figure class="shot" style="--w:600px;"><img src="'+p+'" alt="" width="600" loading="lazy"></figure><p><strong>Field Name</strong> - You can change the name of the section according to your needs. This has no effect on its functionality.</p><p><strong>Abreviation</strong> - allows you to change the text used in the daily report and in the mobile application.</p><p><strong>Section Item Settings</strong> – provides the list of available fields that can be used in the given section. If you want to reduce the number of displayed fields, select <strong>Hide</strong>. If you want to ensure that a particular field is always completed, set it to <strong>Mandatory</strong>.</p><p><strong>Entry Timestamp</strong> - displays the time when an entry was created and highlights entries created after the statutory deadline. It defines whether and how the entry timestamp should be displayed, with three options: <strong>Hide</strong> = Do not display at all <strong>Show</strong> = Simply display the date and time when the entry was created or last modified <strong>Required</strong> = In addition to displaying the date and time, the icon for entries created after the statutory deadline is visually highlighted and the number of hours by which the statutory deadline was exceeded is displayed.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The statutory deadline is 48 hours, excluding days marked as &quot;Non-Working&quot; (up to a maximum of 2 days). Entries created or edited after this limit are marked with a red exclamation-mark icon. Hovering over the icon displays the date, time, and number of hours beyond the statutory deadline.</p></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>If you change any setting, save it using the <strong>Save</strong> button. <strong>Each tab must be saved separately.</strong></p></div><h3 id="individual-section-tabs-specific-information" tabindex="-1">Individual Section Tabs - Specific Information <a class="header-anchor" href="#individual-section-tabs-specific-information" aria-label="Permalink to &quot;Individual Section Tabs - Specific Information&quot;">​</a></h3><h4 id="weather" tabindex="-1">Weather <a class="header-anchor" href="#weather" aria-label="Permalink to &quot;Weather&quot;">​</a></h4><p><strong>Weather entry hours</strong> - In this tab, you set the full-hour times at which you want weather data to be retrieved. The default values are 6:00, 12:00, and 18:00. You can add additional times using the code list by clicking the selected time, or remove a time from the selected hours using the x button. A row containing weather data will then be generated for each selected hour in the daily entries.</p><p><strong>Siotech Sensor</strong> - enter the device ID in this field if you use an autonomous Siotech temperature sensor (see <a href="/buildary-help-preview/en/diary/sensors">Digital Sensors</a>).</p><h4 id="works-performed-and-other-entries" tabindex="-1">Works Performed and Other Entries <a class="header-anchor" href="#works-performed-and-other-entries" aria-label="Permalink to &quot;Works Performed and Other Entries&quot;">​</a></h4><p>In the Works Performed section, you can also enter records using budget items. To do this, you need to have the Project&#39;s budget uploaded, set the <strong>Item Description</strong> field to Show, and select the entire construction site or a specific part of it in the <strong>Cost estimate items filtration</strong> field.</p><p><strong>Location</strong> - displays a map showing the location to which the entry relates. The coordinates are loaded automatically from GPS (location services must be enabled on a mobile device), or the user can determine the location by clicking on the map. When the coordinates are loaded, the time at which they were obtained from GPS is also saved.</p><p><strong>Plan</strong> - allows a drawing to be displayed for an entry and a marker to be placed on it by clicking on the location to which the diary entry relates. To use this function, plans of the construction site must first be uploaded to the Project Sections and Plans code list.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>If you have a larger number of construction sites in Buildary and the default settings do not meet your needs, you can create one or more Project Templates where you can define your own template diary settings. A Project Template is created by a user with Domain Administration permissions.</p></div>',49)])])}const k=i(u,[["render",y]]);export{S as __pageData,k as default};
